"""Self-contained, accessible impact explorer. Source values enter DOM as text only."""
import json


def section(graph):
    payload=json.dumps(graph,ensure_ascii=True).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return '''<h2 id="impact-heading">Upstream &amp; downstream impact</h2>
<section class="panel" aria-labelledby="impact-heading">
<p>Explore source references, possible activation paths and security boundaries. Arrows are dependencies, not proof of runtime execution or authorisation.</p>
<div class="toolbar"><label class="impact-control">Component or method<select id="impact-focus" aria-label="Impact focus"></select></label><label class="impact-control">Direction<select id="impact-direction"><option value="both">Both directions</option><option value="upstream">Upstream callers</option><option value="downstream">Downstream dependencies</option></select></label><label class="impact-control">Depth<select id="impact-depth"><option>1</option><option selected>2</option><option>3</option><option>4</option></select></label></div>
<p id="impact-summary" aria-live="polite" class="muted"></p><p class="impact-legend"><span>● Explicit reference</span><span class="conditional">● Conditional relationship</span><span class="unresolved">● Unresolved target</span></p>
<div class="impact-map" tabindex="0" aria-label="Scrollable dependency map"><svg id="impact-svg" role="img" aria-label="Dependency map"></svg></div>
<p class="muted">Select a node to refocus. Select a connection below to inspect its evidence. Containment is included in component scope but is not drawn as an execution step.</p>
<div class="table-wrap impact-connections"><table><thead><tr><th>Source → target</th><th>Relationship</th><th>Confidence</th><th>Evidence</th></tr></thead><tbody id="impact-connections"></tbody></table></div>
<section id="impact-evidence" class="impact-evidence" aria-live="polite"><h3>Connection evidence</h3><p>Select a relationship to see its source location and limits.</p></section>
<details><summary>Review boundaries and suggested regression checks</summary><ul id="impact-tests"></ul><h3>Unresolved analysis</h3><ul id="impact-gaps"></ul><p class="muted">These checks are suggested, not executed. Missing metadata, dynamic queries, overloads, inheritance and runtime configuration can hide additional paths.</p></details></section>
<script id="impact-data" type="application/json">''' + payload + '</script>'


CSS='''
.impact-control{display:flex;flex-direction:column;gap:6px;flex:1;min-width:130px;font-size:13px;color:var(--muted)}.impact-control:first-child{flex:3;min-width:210px}.impact-control select{width:100%;max-width:100%;font-size:13px}.impact-map{max-height:570px;overflow:auto;border:1px solid var(--border);border-radius:10px;background:#0a1221}.impact-map svg{display:block;max-width:none}.impact-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:#6ee7c1}.conditional{color:#f9d88b}.unresolved{color:#f6a6bb}.impact-connections{max-height:330px;overflow:auto;margin-top:18px}.impact-evidence{padding:14px 0}.impact-link,button.inspect-impact{border:1px solid #4c607c;background:#18283e;color:#b8f6e3;border-radius:6px;padding:6px 10px;font:inherit;cursor:pointer;text-align:left}button.inspect-impact{margin-top:12px;font-size:13px}.impact-link:focus-visible,button.inspect-impact:focus-visible{outline:2px solid #6ee7c1;outline-offset:2px}#impact-evidence p{overflow-wrap:anywhere}#impact-evidence pre{max-height:180px;overflow:auto}
'''

JS=r'''
const impactGraph=JSON.parse(document.getElementById('impact-data').textContent);
const impactNodes=new Map(impactGraph.nodes.map(n=>[n.id,n]));
const impactFocus=document.getElementById('impact-focus'),impactDirection=document.getElementById('impact-direction'),impactDepth=document.getElementById('impact-depth');
const words=s=>String(s||'').replaceAll('_',' ');
function textElement(tag,text,parent){const e=document.createElement(tag);e.textContent=text;if(parent)parent.appendChild(e);return e;}
function svgElement(tag,attrs,parent){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs||{}).forEach(([k,v])=>e.setAttribute(k,v));if(parent)parent.appendChild(e);return e;}
impactGraph.nodes.filter(n=>!['unresolved','external_flow'].includes(n.kind)).sort((a,b)=>a.label.localeCompare(b.label)).forEach(n=>{const option=document.createElement('option');option.value=n.id;option.textContent=n.label+' · '+words(n.kind);impactFocus.appendChild(option);});
const defaultFocus=impactGraph.nodes.find(n=>n.kind==='apex_method'&&n.entry_points?.includes('AuraEnabled'))||impactGraph.nodes[0];
if(defaultFocus)impactFocus.value=defaultFocus.id;
function impactSlice(){const focus=impactFocus.value,direction=impactDirection.value,depth=Number(impactDepth.value);const seeds=new Set([focus]);
if(['apex_class','flow'].includes(impactNodes.get(focus)?.kind))impactGraph.edges.filter(e=>e.source===focus&&e.kind==='contains').forEach(e=>seeds.add(e.target));
let truncated=seeds.size>120;if(truncated){const keep=[focus,...[...seeds].filter(x=>x!==focus).sort().slice(0,119)];seeds.clear();keep.forEach(x=>seeds.add(x));}
const selected=new Set(seeds),edgeIds=new Set(),levels=new Map([...seeds].map(n=>[n,0]));
for(const way of(direction==='both'?['upstream','downstream']:[direction])){const queue=[...[...seeds].map(n=>[n,0])],visited=new Set(seeds);
for(let q=0;q<queue.length;q++){const[current,distance]=queue[q];if(distance>=depth)continue;
for(const e of impactGraph.edges){if(e.kind==='contains')continue;const match=way==='upstream'?e.target===current:e.source===current;if(!match)continue;const other=way==='upstream'?e.source:e.target;
if(!selected.has(other)&&selected.size>=120){truncated=true;continue;}selected.add(other);edgeIds.add(e.id);if(!levels.has(other))levels.set(other,(distance+1)*(way==='upstream'?-1:1));if(!visited.has(other)){visited.add(other);queue.push([other,distance+1]);}}}}
return{focus,nodes:impactGraph.nodes.filter(n=>selected.has(n.id)),edges:impactGraph.edges.filter(e=>edgeIds.has(e.id)),levels,truncated};}
function inspectConnection(edge){const box=document.getElementById('impact-evidence');box.replaceChildren();textElement('h3',words(edge.kind)+' · '+words(edge.confidence),box);textElement('p',impactNodes.get(edge.source).label+' → '+impactNodes.get(edge.target).label,box);textElement('p',edge.evidence.path+':'+edge.evidence.line,box);textElement('pre',edge.evidence.excerpt,box);if(edge.note)textElement('p',edge.note,box);
for(const key of ['mode','boundary','transaction_model','operation'])if(edge[key])textElement('p',words(key)+': '+words(edge[key]),box);textElement('p','A static reference does not establish end-user permission, guard effectiveness or runtime path feasibility.',box);}
function showImpact(){if(!impactFocus.value){document.getElementById('impact-summary').textContent='No supported component node selected on this side. Review the other side and snapshot evidence.';for(const id of ['impact-svg','impact-connections','impact-evidence','impact-tests','impact-gaps'])document.getElementById(id).replaceChildren();return;}const slice=impactSlice(),focus=impactNodes.get(slice.focus);
document.getElementById('impact-summary').textContent=slice.nodes.length+' nodes · '+slice.edges.length+' connections · '+slice.edges.filter(e=>e.confidence==='unresolved').length+' unresolved connections · '+impactGraph.gaps.length+' extraction gaps overall'+(slice.truncated?' · View capped at 120 nodes; narrow the focus.':'')+' · Source view only';
const svg=document.getElementById('impact-svg');svg.replaceChildren();const columns=new Map();slice.nodes.forEach(n=>{const level=slice.levels.get(n.id)||0;if(!columns.has(level))columns.set(level,[]);columns.get(level).push(n);});const levels=[...columns.keys()].sort((a,b)=>a-b),width=Math.max(720,levels.length*285),height=Math.max(240,...[...columns.values()].map(v=>v.length*100+65)),positions=new Map();svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);
const title=svgElement('title',{},svg);title.textContent='Static impact around '+focus.label;const defs=svgElement('defs',{},svg),marker=svgElement('marker',{id:'impact-arrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:6,markerHeight:6,orient:'auto-start-reverse'},defs);svgElement('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#9cb69d'},marker);
levels.forEach((level,index)=>{const heading=svgElement('text',{x:index*285+22,y:26,fill:'#b5c9b8','font-size':12},svg);heading.textContent=level<0?'UPSTREAM '+Math.abs(level):level>0?'DOWNSTREAM '+level:'SELECTED SCOPE';columns.get(level).forEach((n,row)=>positions.set(n.id,{x:index*285+16,y:45+row*100}));});
slice.edges.forEach(edge=>{const a=positions.get(edge.source),b=positions.get(edge.target);if(!a||!b)return;const color=edge.confidence==='conditional'?'#c7ad68':edge.confidence==='unresolved'?'#df8b70':'#91b895';const forward=b.x>a.x;const path=svgElement('path',{d:`M ${a.x+(forward?245:0)} ${a.y+36} C ${a.x+(forward?275:-30)} ${a.y+36}, ${b.x+(forward?-30:275)} ${b.y+36}, ${b.x+(forward?0:245)} ${b.y+36}`,fill:'none',stroke:color,'stroke-width':1.5,'stroke-dasharray':edge.confidence==='explicit_reference'?'':'5 4','marker-end':'url(#impact-arrow)'},svg);const t=svgElement('title',{},path);t.textContent=words(edge.kind)+' · '+words(edge.confidence);});
slice.nodes.forEach(n=>{const p=positions.get(n.id),g=svgElement('g',{tabindex:0,role:'button','aria-label':'Focus '+n.label},svg);g.style.cursor='pointer';const border=n.id===slice.focus?'#d8ed79':n.kind==='unresolved'?'#df8b70':n.finding_ids?.length?'#f9d88b':'#4c6854';svgElement('rect',{x:p.x,y:p.y,width:245,height:76,rx:3,fill:'#183329',stroke:border,'stroke-width':n.id===slice.focus?2:1},g);const lines=[n.label.slice(0,30),n.label.length>30?n.label.slice(30,59):words(n.kind)];lines.forEach((line,i)=>{const t=svgElement('text',{x:p.x+12,y:p.y+23+i*18,fill:i?'#b5c9b8':'#f5f6e7','font-size':12},g);t.textContent=line;});const meta=svgElement('text',{x:p.x+12,y:p.y+63,fill:'#f9d88b','font-size':10},g);meta.textContent=n.finding_ids?.length?n.finding_ids.length+' review signals':n.api_version?'API '+n.api_version:n.sharing?words(n.sharing):'';const title=svgElement('title',{},g);title.textContent=n.label+' · '+n.path+':'+n.line+' · '+words(n.sharing||'');const choose=()=>{if(![...impactFocus.options].some(o=>o.value===n.id)){const o=document.createElement('option');o.value=n.id;o.textContent=n.label;impactFocus.appendChild(o);}impactFocus.value=n.id;showImpact();};g.addEventListener('click',choose);g.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();choose();}});});
const tbody=document.getElementById('impact-connections');tbody.replaceChildren();slice.edges.forEach(edge=>{const row=document.createElement('tr');textElement('td',impactNodes.get(edge.source).label+' → '+impactNodes.get(edge.target).label,row);textElement('td',words(edge.kind),row);textElement('td',words(edge.confidence),row);const cell=textElement('td','',row),button=textElement('button',edge.evidence.path+':'+edge.evidence.line,cell);button.type='button';button.className='impact-link';button.addEventListener('click',()=>inspectConnection(edge));tbody.appendChild(row);});if(!slice.edges.length){const row=textElement('tr','',tbody),cell=textElement('td','No explicit references found in this scope. Missing source or dynamic dispatch can hide dependencies.',row);cell.colSpan=4;}
const tests=document.getElementById('impact-tests');tests.replaceChildren();textElement('li','Verify allowed and denied callers. References do not establish authorisation.',tests);const kinds=new Set(slice.edges.map(e=>e.kind));if(kinds.has('writes')||kinds.has('may_activate'))textElement('li','Test expected record changes, denied side effects, entry criteria, bulk behaviour and recursion.',tests);if(kinds.has('enqueues')||kinds.has('schedules')||slice.edges.some(e=>e.boundary==='asynchronous'))textElement('li','Test async revalidation, stale or replayed work, principal changes and duplicate execution.',tests);if(kinds.has('fault'))textElement('li','Test fault routing, rollback, recovery eligibility and safe diagnostics.',tests);if(kinds.has('reads')||kinds.has('reads_field')||kinds.has('grants_field_access'))textElement('li','Test least-privileged CRUD/FLS and record visibility; review privileged exceptions separately.',tests);
const gaps=document.getElementById('impact-gaps');gaps.replaceChildren();const paths=new Set(slice.nodes.map(n=>n.path));const relevant=impactGraph.gaps.filter(g=>g.path==='.'||paths.has(g.path)||slice.nodes.some(n=>n.id===g.component));relevant.slice(0,50).forEach(g=>textElement('li',g.path+':'+g.line+' — '+g.reason,gaps));if(!relevant.length)textElement('li','No extraction gaps recorded for these paths. This does not establish complete impact coverage.',gaps);if(impactGraph.gaps.length>relevant.length)textElement('li',(impactGraph.gaps.length-relevant.length)+' additional gaps exist in other source scopes.',gaps);
document.getElementById('impact-evidence').replaceChildren();textElement('h3',focus.label,document.getElementById('impact-evidence'));textElement('p',[focus.path+':'+focus.line,focus.api_version?'API '+focus.api_version:'',focus.sharing?'Sharing: '+words(focus.sharing):'',focus.declared_mode?'Declared Flow mode: '+words(focus.declared_mode):''].filter(Boolean).join(' · '),document.getElementById('impact-evidence'));const owners=new Set(slice.nodes.filter(n=>['apex_class','apex_method'].includes(n.kind)).map(n=>n.owner||n.id));const grants=impactGraph.edges.filter(e=>e.kind==='grants_class_access'&&owners.has(e.target));if(grants.length){textElement('h3','Declared class-access context',document.getElementById('impact-evidence'));for(const e of grants){textElement('p',impactNodes.get(e.source).label+' grants access to '+impactNodes.get(e.target).label+' · '+e.evidence.path+':'+e.evidence.line,document.getElementById('impact-evidence'));}textElement('p','These are metadata grants, not proof of assignment or effective user access.',document.getElementById('impact-evidence'));}}
impactFocus.addEventListener('change',showImpact);impactDirection.addEventListener('change',showImpact);impactDepth.addEventListener('change',showImpact);showImpact();
document.querySelectorAll('.inspect-impact').forEach(button=>button.addEventListener('click',()=>{const candidates=impactGraph.nodes.filter(n=>n.finding_ids?.includes(button.dataset.finding));const chosen=candidates.find(n=>n.kind==='apex_method')||candidates[0];if(chosen){impactFocus.value=chosen.id;showImpact();document.getElementById('impact-heading').scrollIntoView({behavior:'smooth'});}}));
'''
